// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PoCGame} from "../src/PoCGame.sol";

contract InvMutTest is Test {
    PoCGame c;
    FakeToken token;

    function setUp() public { c = new PoCGame(address(this), 0); }

    function testFuzz_property(bool transferSucceeds, uint256 tokens, address tokenOwner) public {
        token = new FakeToken(transferSucceeds);
        if (tokens > type(uint256).max / 2) tokens = type(uint256).max / 2;
        bool ok = c.transferAnyERC20Token(address(token), tokenOwner, tokens);
        bool expected = token.lastResult();
        assertTrue(ok == expected);
    }
}

contract FakeToken {
    bool private result;
    bool private last;
    constructor(bool r) { result = r; }
    function transfer(address to, uint256 tokens) public returns (bool success) {
        last = result;
        return result;
    }
    function lastResult() public view returns (bool) { return last; }
}
